40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const PROCESSING_FEE = 5;
43	
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Premiums round in the MHPCO's favour: always up. */
56	const roundPremium = (premium: number): number => Math.ceil(premium);
57	
58	/**
59	 * Exactly this many items of one type form a "building block", priced at a flat
60	 * rate instead of per item. A larger group is NOT a block -- 4 runes pay 4x25 G.
61	 */
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	/** How many items of each type the policy covers -- the unit the block rule applies to. */
66	const countItemsPerType = (items: Item[]): Map<string, number> =>
67	  items.reduce(
68	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
69	    new Map<string, number>(),
70	  );
71	
72	/** Unknown types price at 0 G for now; the spec calls for an error (not yet tested). */
73	const basePremiumPerItem = (type: string): number => BASE_PREMIUMS[type] ?? 0;
74	
75	const basePremiumForType = (type: string, count: number): number =>
76	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumPerItem(type);
77	
78	const policyBasePremium = (items: Item[]): number =>
79	  [...countItemsPerType(items)].reduce(
80	    (total, [type, count]) => total + basePremiumForType(type, count),
81	    0,
82	  );
83	
84	/** A customer with AT LEAST this many years of business is long-standing. */
85	const LOYALTY_THRESHOLD_YEARS = 2;
86	const LOYALTY_DISCOUNT_RATE = 0.2;
87	
88	const CURSE_SURCHARGE_RATE = 0.5;
89	
90	/** An enchantment AT this level or above is "high" -- level 4 carries no surcharge. */
91	const HIGH_ENCHANTMENT_LEVEL = 5;
92	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
93	
94	/** Item-scoped surcharges stack additively: a cursed, highly enchanted item pays both. */
95	const itemSurchargeRate = (item: Item): number =>
96	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
97	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
98	
99	/** Item-scoped surcharges apply to the affected item's own base premium. */
100	const itemSurchargeTotal = (items: Item[]): number =>
101	  items.reduce(
102	    (total, item) => total + basePremiumPerItem(item.type) * itemSurchargeRate(item),
103	    0,
104	  );
105	
106	/**
107	 * Policy-scoped modifiers stack additively, like the item-scoped ones.
108	 * Discounts join the sum as negative rates. The follow-up contract discount
109	 * will be one more term here.
110	 */
111	const isLongStanding = (customer: Customer): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
113	
114	const policyModifierRate = (customer: Customer): number =>
115	  FIRST_INSURANCE_SURCHARGE_RATE - (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0);
116	
117	/**
118	 * Policy-scoped modifiers apply to the policy base premium, never to item
119	 * surcharges.
120	 *
121	 * Returns the modifier AMOUNT, not a multiplier on the base. Folding this into
122	 * `policyBase * (1 + rate)` is algebraically identical but NOT identical in
123	 * floating point: 100 * 1.1 is 110.00000000000001, which `roundPremium` ceils
124	 * to 111 G. Keeping base and modifier as separate addends keeps the exact
125	 * values the spec's worked examples expect.
126	 */
127	const policyModifierTotal = (policyBase: number, customer: Customer): number =>
128	  policyBase * policyModifierRate(customer);
129	
130	const quote = (step: QuoteStep, customer: Customer): Result => {
131	  const policyBase = policyBasePremium(step.items);
132	  return {
133	    premium: roundPremium(
134	      policyBase +
135	        policyModifierTotal(policyBase, customer) +
136	        itemSurchargeTotal(step.items) +
137	        PROCESSING_FEE,
138	    ),
139	  };
140	};
141	
142	const resultOf = (step: Step, customer: Customer): Result => {
143	  if (step.op === "quote") return quote(step, customer);
144	  throw new Error(`Unsupported operation: ${step.op}`);
145	};
146	
147	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
148	  results: scenario.steps.map((step) => resultOf(step, scenario.customer)),
149	});
