/** The per-item rate for a type. Unknown types price at 0 G for now; the spec calls for an error (not yet tested). */
const basePremiumRate = (type: string): number => BASE_PREMIUMS[type] ?? 0;

const basePremiumForType = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumRate(type);

const policyBasePremium = (items: Item[]): number =>
  [...countItemsPerType(items)].reduce(
    (total, [type, count]) => total + basePremiumForType(type, count),
};

const runStep = (step: Step, customer: Customer): Result => {
  if (step.op === "quote") return quote(step, customer);
  throw new Error(`Unsupported operation: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});
